import codecs,json,sys,unicodedata,traceback,platform
cases=json.load(open('/tmp/codec-source-context-cases.json')); rows=[]
for case in cases:
 for mode in ('compile','exec','eval'):
  ns={'__name__':'__main__'}
  target='guest-codec.py' if mode=='compile' else '<string>'
  def decoder(*args):ns['decode']();raise AssertionError('decoder returned')
  def search(name):return codecs.CodecInfo(None,decoder,name=name) if name=='guest_fault' else None
  def trigger():
   source=b'# coding: guest-fault\n1'
   return compile(source,target,'exec') if mode=='compile' else (exec(source,{}) if mode=='exec' else eval(source,{}))
  ns.update(trigger=trigger,target=target,preserve_filename=mode=='compile')
  codecs.register(search)
  try:
   exec(case['source'],ns)
   result='ok'
  except BaseException as error:result=traceback.format_exc()
  finally:codecs.unregister(search)
  rows.append(dict(name=case['name'],mode=mode,result=result))
json.dump(dict(oracle=dict(version=sys.version,unicode=unicodedata.unidata_version,byteorder=sys.byteorder,platform=platform.platform()),rows=rows),open('/tmp/codec-source-context-oracle.json','w'),indent=2)
for row in rows:
 if row['result']!='ok':print(row['mode'],row['name'],ascii(row['result']))
print('matches',sum(row['result']=='ok' for row in rows),'total',len(rows))

